  "search": "'use client';\n\nimport React from 'react';\nimport { Cascader } from '@ceebee/ui/client';\nimport type { CascaderProps, GetProp } from '@ceebee/ui/client';\n\ntype DefaultOptionType = GetProp<CascaderProps, 'options'>[number];\n\ninterface Option {\n  value: string;\n  label: string;\n  children?: Option[];\n  disabled?: boolean;\n}\n\nconst options: Option[] = [\n  {\n    value: 'zhejiang',\n    label: 'Zhejiang',\n    children: [\n      {\n        value: 'hangzhou',\n        label: 'Hangzhou',\n        children: [\n          {\n            value: 'xihu',\n            label: 'West Lake',\n          },\n          {\n            value: 'xiasha',\n            label: 'Xia Sha',\n            disabled: true,\n          },\n        ],\n      },\n    ],\n  },\n  {\n    value: 'jiangsu',\n    label: 'Jiangsu',\n    children: [\n      {\n        value: 'nanjing',\n        label: 'Nanjing',\n        children: [\n          {\n            value: 'zhonghuamen',\n            label: 'Zhong Hua men',\n          },\n        ],\n      },\n    ],\n  },\n];\n\nconst onChange: CascaderProps<Option>['onChange'] = (value, selectedOptions) => {\n  console.log(value, selectedOptions);\n};\n\nconst filter = (inputValue: string, path: DefaultOptionType[]) =>\n  path.some((option) => (option.label as string).toLowerCase().includes(inputValue.toLowerCase()));\n\nconst App: React.FC = () => (\n  <Cascader\n    options={options}\n    onChange={onChange}\n    placeholder=\"Please select\"\n    showSearch={{ filter, onSearch: (value) => console.log(value) }}\n  />\n);\n\nexport default App;\n",
